'use strict';
(()=>{let directoryBranch='all';const beforeCustomers=customersHTML,beforeRows=customerRows;
customerRows=function(members){const list=directoryBranch==='all'?members:members.filter(m=>(m.registrationBranchId||'')===directoryBranch),box=document.createElement('tbody');box.innerHTML=beforeRows(list);if(!list.length){box.querySelector('td').colSpan=7;return box.innerHTML;}Array.from(box.querySelectorAll('tr')).forEach((row,i)=>{const name=document.createElement('td'),branch=document.createElement('td');name.textContent=shop().card.title||shop().name;branch.textContent=typeof branchLabel==='function'?branchLabel(list[i].registrationBranchId||''):'بدون فرع';row.append(name,branch);});return box.innerHTML;};
customersHTML=function(){const box=document.createElement('div');box.innerHTML=beforeCustomers();const s=shop(),business=s.business||s.id,cards=db.shops.filter(c=>!c.archivedAt&&(c.business||c.id)===business),base=db.shops.find(c=>c.id===business),branches=base?.branches||[];if(directoryBranch!=='all'&&directoryBranch!==''&&!branches.some(b=>b.id===directoryBranch))directoryBranch='all';box.querySelector('.search-row')?.insertAdjacentHTML('beforebegin',`<div class="form-row"><label class="field"><span>بطاقة الولاء</span><select data-directory-card>${cards.map(c=>`<option value="${esc(c.id)}" ${c.id===s.id?'selected':''}>${esc(c.card.title||c.name)}</option>`).join('')}</select></label><label class="field"><span>فرع تسجيل العميل</span><select data-directory-branch><option value="all">جميع الفروع</option><option value="" ${directoryBranch===''?'selected':''}>بدون فرع</option>${branches.map(b=>`<option value="${esc(b.id)}" ${b.id===directoryBranch?'selected':''}>${esc(b.name)}</option>`).join('')}</select></label></div>`);const head=box.querySelector('thead tr');if(head)head.insertAdjacentHTML('beforeend','<th>برنامج الولاء</th><th>فرع التسجيل</th>');if(role==='owner'&&typeof adminScope!=='undefined'&&adminScope)box.querySelector('.panel')?.insertAdjacentHTML('beforeend','<p class="sub mt">إدارة أرقام الحملات وتصنيفها متاحة من قسم تسويق واتساب في الإدارة.</p>');return box.innerHTML;};
document.addEventListener('change',e=>{if(e.target.matches('[data-directory-branch]')){directoryBranch=e.target.value;render();}if(e.target.matches('[data-directory-card]')){const c=db.shops.find(c=>c.id===e.target.value),s=shop();if(c&&!c.archivedAt&&(c.business||c.id)===(s.business||s.id)){db.shop=c.id;directoryBranch='all';render();}}});render();})();
